func (d *Deferred) HaveAnyDeferrals() bool {
	d.mu.Lock()
	defer d.mu.Unlock()

	return d.deferralAllowed &&
		(d.externalDependencyDeferred ||
			d.resourceInstancesDeferred.Len() != 0 ||
			d.dataSourceInstancesDeferred.Len() != 0 ||
